package vn.iotstar.controller;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;import vn.iotstar.service.*;@Controller public class HomeController{public HomeController(UserService users,ProductService products){this.users=users;this.products=products;}final UserService users;final ProductService products;@GetMapping("/")public String home(Model m){m.addAttribute("userCount",users.countUsers());m.addAttribute("productCount",products.countProducts());return "home";}@GetMapping("/access-denied")public String denied(){return "error";}}
